(function() {
    'use strict';

    class TurismoRegionalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Turismo y Economía Regional en Colombia';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    tag: 'round1_tag',
                    title: 'round1_title',
                    brief: 'round1_brief',
                    duration: '20 min',
                    investmentMin: 50,
                    investmentMax: 800,
                    baseVisitors: 120,
                    environmentalCapacity: 200,
                    seasonMultiplier: 0.85
                },
                {
                    tag: 'round2_tag',
                    title: 'round2_title',
                    brief: 'round2_brief',
                    duration: '30 min',
                    investmentMin: 100,
                    investmentMax: 1200,
                    baseVisitors: 180,
                    environmentalCapacity: 250,
                    seasonMultiplier: 1.15
                },
                {
                    tag: 'round3_tag',
                    title: 'round3_title',
                    brief: 'round3_brief',
                    duration: '25 min',
                    investmentMin: 100,
                    investmentMax: 1500,
                    baseVisitors: 220,
                    environmentalCapacity: 280,
                    seasonMultiplier: 1.0
                },
                {
                    tag: 'round4_tag',
                    title: 'round4_title',
                    brief: 'round4_brief',
                    duration: '15 min',
                    investmentMin: 200,
                    investmentMax: 2000,
                    baseVisitors: 260,
                    environmentalCapacity: 300,
                    seasonMultiplier: 1.25
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000,
                    totalRevenue: 0,
                    communityIndex: 30,
                    sustainabilityScore: 50,
                    gdpImpact: 0.8,
                    totalVisitors: 0,
                    reputation: 50,
                    environmentalHealth: 80,
                    revenueHistory: [],
                    communityHistory: [],
                    sustainabilityHistory: [],
                    gdpHistory: [],
                    cashHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    investment: 200,
                    communityShare: 15,
                    strategy: 'ecotourism',
                    capacity: 'conservative'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var investmentInput = document.getElementById('investmentInput');
            if (investmentInput) decisions.investment = parseFloat(investmentInput.value);

            var communityShareInput = document.getElementById('communityShareInput');
            if (communityShareInput) decisions.communityShare = parseFloat(communityShareInput.value);

            var strategySelect = document.getElementById('strategySelect');
            if (strategySelect) decisions.strategy = strategySelect.value;

            var capacitySelect = document.getElementById('capacitySelect');
            if (capacitySelect) decisions.capacity = capacitySelect.value;

            var roundIdx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            if (!decisions.investment || decisions.investment < round.investmentMin || decisions.investment > round.investmentMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('investment_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.communityShare || decisions.communityShare < 5 || decisions.communityShare > 60) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('community_share_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var strategyMultipliers = {
                ecotourism:  { revenue: 0.8,  community: 1.4, sustainability: 1.5, visitors: 0.7 },
                cultural:    { revenue: 0.9,  community: 1.3, sustainability: 1.2, visitors: 0.85 },
                adventure:   { revenue: 1.3,  community: 0.7, sustainability: 0.7, visitors: 1.3 },
                mixed:       { revenue: 1.05, community: 1.0, sustainability: 1.0, visitors: 1.05 }
            };
            var sm = strategyMultipliers[d.strategy] || strategyMultipliers.mixed;

            var capacityMultipliers = {
                conservative: { visitors: 0.6, envImpact: 0.3, cost: 0.7 },
                moderate:     { visitors: 1.0, envImpact: 0.6, cost: 1.0 },
                aggressive:   { visitors: 1.5, envImpact: 1.2, cost: 1.4 }
            };
            var cm = capacityMultipliers[d.capacity] || capacityMultipliers.moderate;

            var baseVisitors = round.baseVisitors * round.seasonMultiplier;
            var visitors = Math.round(baseVisitors * sm.visitors * cm.visitors * (1 + ds.reputation / 200));

            var overCapacity = visitors > round.environmentalCapacity;
            if (overCapacity) {
                visitors = Math.round(round.environmentalCapacity * 1.1);
            }

            var avgSpendPerVisitor = 350;
            var reputationBonus = 1 + (ds.reputation - 50) / 250;
            var grossRevenue = Math.round(visitors * avgSpendPerVisitor * sm.revenue * reputationBonus);

            var operationalCost = Math.round(d.investment * 0.6 + visitors * 85 * cm.cost);
            var communityTransfer = Math.round(grossRevenue * (d.communityShare / 100));
            var netRevenue = grossRevenue - operationalCost - communityTransfer;

            ds.cash += netRevenue;
            ds.totalRevenue += grossRevenue;
            ds.totalVisitors += visitors;

            var communityDelta = (d.communityShare - 10) * 1.2 * sm.community + (d.investment * 0.008);
            if (overCapacity) communityDelta -= 8;
            ds.communityIndex = Math.max(0, Math.min(100, ds.communityIndex + communityDelta));
            ds.communityIndex = Math.round(ds.communityIndex * 10) / 10;

            var sustainDelta = (sm.sustainability - 1) * 20 - cm.envImpact * 8 + (d.communityShare / 10);
            if (overCapacity) sustainDelta -= 12;
            sustainDelta += d.investment * 0.005;
            ds.sustainabilityScore = Math.max(0, Math.min(100, ds.sustainabilityScore + sustainDelta));
            ds.sustainabilityScore = Math.round(ds.sustainabilityScore * 10) / 10;

            ds.environmentalHealth = Math.max(0, Math.min(100, ds.environmentalHealth - cm.envImpact * 5 + sm.sustainability * 3));
            if (overCapacity) ds.environmentalHealth -= 8;

            var reputationDelta = 0;
            if (ds.communityIndex > 50) reputationDelta += 3;
            if (ds.sustainabilityScore > 60) reputationDelta += 4;
            if (overCapacity) reputationDelta -= 7;
            if (netRevenue > 0) reputationDelta += 2;
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + reputationDelta));

            var gdpDelta = (grossRevenue / 50000) * 0.1 + (communityTransfer / 30000) * 0.15;
            if (overCapacity) gdpDelta *= 0.5;
            ds.gdpImpact = Math.round((ds.gdpImpact + gdpDelta) * 100) / 100;

            ds.revenueHistory.push(grossRevenue);
            ds.communityHistory.push(ds.communityIndex);
            ds.sustainabilityHistory.push(ds.sustainabilityScore);
            ds.gdpHistory.push(ds.gdpImpact);
            ds.cashHistory.push(ds.cash);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            if (state.currentPeriod >= (state.maxPeriods || this.ROUNDS.length)) { var selfC = this; setTimeout(function() { try { selfC._renderCompletion(state); } catch (e) {} }, 0); }

            return {
                period: state.currentPeriod,
                visitors: visitors,
                grossRevenue: grossRevenue,
                operationalCost: operationalCost,
                communityTransfer: communityTransfer,
                netRevenue: netRevenue,
                communityIndex: ds.communityIndex,
                sustainabilityScore: ds.sustainabilityScore,
                gdpImpact: ds.gdpImpact,
                cash: ds.cash,
                overCapacity: overCapacity
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('communityDisplay', 'domainState.communityIndex',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('sustainabilityDisplay', 'domainState.sustainabilityScore',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('gdpDisplay', 'domainState.gdpImpact',
                function(v) { return v.toFixed(2) + '%'; });
        }

        getChartConfig() {
            return {
                revenueChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Ingresos brutos (COP M)',
                            data: [],
                            backgroundColor: 'rgba(255,205,0,0.5)',
                            borderColor: '#ffcd00',
                            borderWidth: 2,
                            borderRadius: 6
                        }, {
                            label: 'Caja acumulada (COP M)',
                            data: [],
                            backgroundColor: 'rgba(0,230,118,0.35)',
                            borderColor: '#00e676',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Desempeño Financiero', color: '#ffffff' },
                            legend: { labels: { color: '#aaa' } }
                        },
                        scales: {
                            x: { ticks: { color: '#aaa' }, grid: { color: 'rgba(255,255,255,0.06)' } },
                            y: { beginAtZero: true, ticks: { color: '#aaa' }, grid: { color: 'rgba(255,255,255,0.06)' } }
                        }
                    }
                },
                indicatorsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Comunidad',
                            data: [],
                            borderColor: '#42a5f5',
                            backgroundColor: 'rgba(66,165,245,0.1)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3
                        }, {
                            label: 'Sostenibilidad',
                            data: [],
                            borderColor: '#66bb6a',
                            backgroundColor: 'rgba(102,187,106,0.1)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3
                        }, {
                            label: 'PIB Regional (%)',
                            data: [],
                            borderColor: '#ef9a9a',
                            backgroundColor: 'rgba(239,154,154,0.1)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Indicadores de Impacto', color: '#ffffff' },
                            legend: { labels: { color: '#aaa' } }
                        },
                        scales: {
                            x: { ticks: { color: '#aaa' }, grid: { color: 'rgba(255,255,255,0.06)' } },
                            y: { min: 0, max: 100, ticks: { color: '#aaa' }, grid: { color: 'rgba(255,255,255,0.06)' } },
                            y1: { position: 'right', min: 0, ticks: { color: '#ef9a9a' }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                revenueChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.cashHistory }
                    ]
                },
                indicatorsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.communityHistory },
                        { data: state.domainState.sustainabilityHistory },
                        { data: state.domainState.gdpHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var totalNet = 0;
            var totalVisitors = 0;
            var i;
            for (i = 0; i < history.length; i++) {
                totalNet += (history[i].results ? history[i].results.netRevenue : 0) || 0;
                totalVisitors += (history[i].results ? history[i].results.visitors : 0) || 0;
            }
            var lastRound = history[history.length - 1].results || {};
            var finalCommunity = lastRound.communityIndex || 0;
            var finalSustain = lastRound.sustainabilityScore || 0;
            var finalGdp = lastRound.gdpImpact || 0;

            var composite = (finalCommunity * 0.3) + (finalSustain * 0.3) + Math.min(finalGdp * 10, 20) + (totalNet > 0 ? 20 : 0);

            var performance = T('perf_beginner');
            if (composite > 40) performance = T('perf_competent');
            if (composite > 60) performance = T('perf_advanced');
            if (composite > 80) performance = T('perf_excellent');

            var insights = [];
            if (finalCommunity > 60) {
                insights.push(T('insight_community_good'));
            } else {
                insights.push(T('insight_community_weak'));
            }
            if (finalSustain > 65) {
                insights.push(T('insight_sustain_good'));
            } else {
                insights.push(T('insight_sustain_weak'));
            }
            if (totalNet < 0) {
                insights.push(T('insight_loss'));
            }

            return {
                totalNetRevenue: totalNet,
                totalVisitors: totalVisitors,
                finalCommunityIndex: finalCommunity,
                finalSustainabilityScore: finalSustain,
                finalGdpImpact: finalGdp,
                composite: Math.round(composite),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.overCapacity) return window.mySimulation.t('hint_overcapacity');
            if (results.netRevenue < 0) return window.mySimulation.t('hint_loss');
            if (state.domainState.communityIndex < 25) return window.mySimulation.t('hint_low_community');
            if (state.domainState.sustainabilityScore < 30) return window.mySimulation.t('hint_low_sustainability');
            if (results.netRevenue > 0 && state.domainState.communityIndex > 50 && state.domainState.sustainabilityScore > 50) {
                return window.mySimulation.t('hint_balanced');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
