        _renderCompletion(state) {
            var panel = document.getElementById('resultsPanel');
            var body = document.getElementById('resultsBody');
            if (!panel || !body) return;
            var summary = {};
            try { summary = this.getPerformanceSummary(state.history || []) || {}; } catch (e) { summary = {}; }
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var comp = (summary.composite != null) ? summary.composite : 0;
            var perf = summary.performance || '';
            var net = (summary.totalNetRevenue != null) ? summary.totalNetRevenue : 0;
            var vis = (summary.totalVisitors != null) ? summary.totalVisitors : 0;
            var insights = summary.insights || [];
            var html = '<div class="turismo-results-grid">';
            html += '<div class="turismo-result-metric"><span class="tr-label">' + T('composite_label') + '</span><span class="tr-value">' + comp + '/100</span></div>';
            html += '<div class="turismo-result-metric"><span class="tr-label">' + T('performance_label') + '</span><span class="tr-value">' + perf + '</span></div>';
            html += '<div class="turismo-result-metric"><span class="tr-label">' + T('total_net_label') + '</span><span class="tr-value">$' + Math.round(net).toLocaleString() + 'M</span></div>';
            html += '<div class="turismo-result-metric"><span class="tr-label">' + T('total_visitors_label') + '</span><span class="tr-value">' + vis.toLocaleString() + '</span></div>';
            html += '</div>';
            if (insights.length) { html += '<p class="turismo-insights-title"><b>' + T('key_insights_label') + '</b></p><ul class="turismo-insights">'; for (var i = 0; i < insights.length; i++) { html += '<li>' + insights[i] + '</li>'; } html += '</ul>'; }
            body.innerHTML = html;
            panel.style.display = 'block';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var tagEl = document.getElementById('roundTag');
            if (tagEl) {
                tagEl.setAttribute('data-i18n', round.tag);
                tagEl.textContent = window.mySimulation ? window.mySimulation.t(round.tag) : '';
            }

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                titleEl.setAttribute('data-i18n', round.title);
                titleEl.textContent = window.mySimulation ? window.mySimulation.t(round.title) : '';
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.setAttribute('data-i18n', round.brief);
                briefEl.textContent = window.mySimulation ? window.mySimulation.t(round.brief) : '';
            }

            var durationEl = document.getElementById('roundDuration');
            if (durationEl) durationEl.textContent = round.duration;

            var investInput = document.getElementById('investmentInput');
            if (investInput) {
                investInput.min = round.investmentMin;
                investInput.max = round.investmentMax;
            }
        }
